from pathlib import Path
import json,hashlib,statistics,time,gzip,base64
B=Path(__file__).resolve().parent;O=B/'r99-parallel-input';R=O/'run'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
f=read(O/'FREEZE.json');s=read(R/'SUMMARY.json');controls=read(R/'prep-controls/RESULTS.json')
assert sha(O/'benchmark.py')==f['benchmark_sha256']
assert all(sha(Path(n))==h for n,h in f['reference_source_sha256'].items())
def peak(events):
 ticks=sorted([(x['start'],1) for x in events]+[(x['end'],-1) for x in events])
 n=top=0
 for _,v in ticks:n+=v;top=max(top,n)
 return top
for c in controls:
 assert c['metric']['jobs']==128 and len(c['metric']['events'])==128
 assert {x['index'] for x in c['metric']['events']}==set(range(128))
 c['actual_peak_copy_concurrency']=peak(c['metric']['events'])
 assert c['actual_peak_copy_concurrency']==c['prep_workers']
cases=[]
for row in s['rows']:
 c=R/row['case'];r=read(c/'RESULT.json');e=read(c/'work/EXECUTION.json');d=read(c/'work/DELIVERY.json');p=read(c/'work/PREP-METRICS.json')
 assert row['valid'] and r['valid'] and r['files_accepted']==6144
 assert d['status']=='VALID' and d['accepted']==d['requested']==128 and d['files']==6144
 assert p['threads']==4 and peak(p['events'])==4
 assert {x['index'] for x in e['results']}==set(range(128))
 assert len({x['pid'] for x in e['results']})==row['workers']
 assert all(x['exit_code']==0 and x['item_acceptance'] for x in e['results'])
 assert all(x['item_acceptance']['original_checks']['pass'] and all(x['item_acceptance']['original_checks']['checks'].values()) for x in e['results'])
 assert r['independent_qa_s']==0 and row['qa_s']==0
 lanes=[{'pid':m['pid'],'count':m['count'],'wall_s':m['stream_wall_s'],'cpu_s':m['job_cpu_s'],'indices':[x['index'] for x in m['results']]} for m in e['lane_metrics']]
 assert all(x['count']==128//row['workers'] for x in lanes)
 cases.append({**row,'actual_prep_threads':p['threads'],'actual_prep_peak':peak(p['events']),'copy_wall_s':p['copy_wall_s'],'lanes':lanes,'match_sum_s':sum(x['match_s'] for x in e['results']),'job_wall_sum_s':sum(x['end']-x['start'] for x in e['results']),'worker_span_s':max(x['end'] for x in e['results'])-min(x['start'] for x in e['results']),'worker_cpu_s':sum(x['cpu_s'] for x in e['results']),'receipt_sha256':sha(c/'RESULT.json')})
prep={}
for w in [1,4]:
 v=[x['wall_s'] for x in controls if x['prep_workers']==w];prep[str(w)]={'mean_s':statistics.mean(v),'range_s':[min(v),max(v)]}
prep['mean_speedup']=prep['1']['mean_s']/prep['4']['mean_s']
prep['pairs_speedup']=[controls[0]['wall_s']/controls[1]['wall_s'],controls[3]['wall_s']/controls[2]['wall_s']]
groups={}
for key in ['production_s','production_with_fixture_s','total_s','total_with_fixture_s']:
 g={}
 for w in [1,4]:
  vals=[r[key] for r in cases if r['workers']==w];g[str(w)]={'mean_s':statistics.mean(vals),'range_s':[min(vals),max(vals)]}
 g['speedup_mean']=g['1']['mean_s']/g['4']['mean_s'];g['pairs']=[cases[0][key]/cases[1][key],cases[3][key]/cases[2][key]];groups[key]=g
packed=base64.b64encode(gzip.compress(json.dumps(controls,separators=(',',':')).encode('utf-8'))).decode('ascii')
compact_controls=[{**c,'metric':{k:v for k,v in c['metric'].items() if k!='events'}} for c in controls]
out={'task_id':f['task_id'],'created_epoch':time.time(),'quality':'VALID','accepted':512,'files_accepted_with_original_per_item_QA':24576,'duplicate_external_payload_audit':'REMOVED_ON_EXPLICIT_USER_STEERING','acceptance_evidence':'all expected fixture input hashes match already-computed original matcher hashes; manifest bound to those hashes per item; original byte/CRC/input QA and receipt/output fingerprint checks unchanged; each job accepted once; no repeat content scan','freeze':f,'freeze_sha256':sha(O/'FREEZE.json'),'source_identity_unchanged':True,'prep_controls':compact_controls,'prep_timings_gzip_base64':packed,'prep_groups':prep,'cases':cases,'groups':groups,'research_prepare_controls_total_s':sum(x['wall_s'] for x in controls),'business_batches_total_including_prepare_s':sum(x['total_with_fixture_s'] for x in cases),'user_message_to_final_reply_T_VALID':'NOT_MEASURED','stable_speedup':'TWO_PAIRS_ONLY_NOT_CERTIFIED','scope':'128 homogeneous48-file exact archive tasks; enhanced Pi fixed mature CLI route, not general model or GUI benchmark'}
(O/'R99-Evidence.json').write_text(json.dumps(out,indent=2),encoding='utf-8')
names=['r99_prepare.py','r99_finalize.py','r99-parallel-input/benchmark.py']
(O/'R99-Source-Snapshot.json').write_text(json.dumps({n:{'sha256':sha(B/n),'content':(B/n).read_text(encoding='utf-8')} for n in names},indent=2),encoding='utf-8')
print(json.dumps({k:v for k,v in out.items() if k not in ['freeze','prep_controls','cases','prep_timings_gzip_base64']}),flush=True)
